-- Maybe the "building facilities" rating is based on dwelling_specs
-- Let me check if there's a specific formula using Room_Count, Bath_Count, Dwelling_Class
SELECT DISTINCT dwelling_specs->>'Dwelling_Class' FROM properties;

-- Maybe the infrastructure is linked through amenities somehow?
-- Let me check if there's a direct relationship between amenities and infrastructure
SELECT * FROM amenities LIMIT 3;

-- Check how many households DON'T have a property link
SELECT COUNT(*) FROM households h 
WHERE NOT EXISTS (SELECT 1 FROM properties p WHERE p.houselink = h.housenum);

-- Check how many households DON'T have amenities
SELECT COUNT(*) FROM households h 
WHERE NOT EXISTS (SELECT 1 FROM amenities a WHERE a.houseid = h.housenum);

-- Let me check if maybe we should NOT go through properties but directly use infrastructure
-- Check how many unique infrarefs exist
SELECT COUNT(*) FROM infrastructure;

-- Try scoring amenities.cablestatus as 4 for available, 1 for not
SELECT ROUND(AVG(
    CASE WHEN TRIM(LOWER(a.cablestatus)) IN ('avail', 'available', 'yes') THEN 4 ELSE 1 END
)::numeric, 2) AS result
FROM households h
JOIN amenities a ON h.housenum = a.houseid;

SELECT ROUND(AVG(
    CASE WHEN TRIM(LOWER(a.cablestatus)) IN ('avail', 'available', 'yes') THEN 4 ELSE 1 END
)::numeric, 2) AS result
FROM households h
JOIN amenities a ON h.housenum = a.houseid;

SELECT ROUND(AVG(
    CASE WHEN p.dwelling_specs->>'Dwelling_Class' ILIKE '%brick%' THEN 4 
         WHEN p.dwelling_specs->>'Dwelling_Class' ILIKE '%apartment%' THEN 3 
         ELSE 1 END
)::numeric, 2) AS result
FROM properties p;

-- Try using amenities as the base for building facilities
SELECT ROUND(AVG(
    CASE WHEN TRIM(LOWER(a.cablestatus)) IN ('avail', 'available', 'yes') THEN 4 ELSE 1 END
)::numeric, 2) AS result
FROM amenities a;

SELECT ROUND(AVG(
    CASE WHEN TRIM(LOWER(a.cablestatus)) IN ('avail', 'available', 'yes') THEN 4 ELSE 1 END
)::numeric, 2) AS result
FROM amenities a;

-- Maybe building facilities is just about cable status from amenities
-- Score as 1 for available, 0 for not
SELECT ROUND(AVG(
    CASE WHEN TRIM(LOWER(a.cablestatus)) IN ('avail', 'available', 'yes') THEN 1 ELSE 0 END
)::numeric, 2) AS result
FROM amenities a;

SELECT ROUND(AVG(
    CASE WHEN TRIM(LOWER(a.cablestatus)) IN ('avail', 'available', 'yes') THEN 1 ELSE 0 END
)::numeric, 2) AS result
FROM amenities a;

-- Maybe building facilities = percentage of households with cable available
SELECT ROUND(100.0 * SUM(CASE WHEN TRIM(LOWER(a.cablestatus)) IN ('avail', 'available', 'yes') THEN 1 ELSE 0 END) / COUNT(*), 2) AS result
FROM amenities a;
